void Solver::bump_var(int var, double coeff) {
    // Apply exponential decay to maintain heap competitiveness
    activity[var] += var_inc * coeff;

    // Scale down less frequently but more aggressively to prevent overflow
    if (activity[var] > 1e150) {
        double scale_factor = 1e-100;
        for (int i = 1; i <= vars; i++) activity[i] *= scale_factor;
        var_inc *= scale_factor;
    }

    // Update heap position if variable is in heap
    if (vsids.inHeap(var)) vsids.update(var);
}
